def pbr(m):
 assert m and m.use_nodes;p=m.node_tree.nodes.get('Principled BSDF');assert p is not None
 assert not any(n.type.startswith('TEX_') for n in m.node_tree.nodes),'No texture nodes'
 assert not any(socket.is_linked for socket in p.inputs),'No linked PBR input'
 values=[]
 for name in ['Base Color','Metallic','Roughness','Alpha','IOR','Specular IOR Level','Transmission Weight','Coat Weight','Coat Roughness','Sheen Weight','Emission Color','Emission Strength']:
  value=p.inputs[name].default_value;values.append((name,tuple(round(float(x),6) for x in value) if hasattr(value,'__len__') else round(float(value),6)))
 values.append(('double_sided',not m.use_backface_culling));return tuple(values)
def matrix64(m):return tuple(tuple(float(m[i][j]) for j in range(4)) for i in range(4))
def mm64(a,b):return tuple(tuple(sum(a[i][k]*b[k][j] for k in range(4)) for j in range(4)) for i in range(4))
def point64(m,p):return tuple(sum(m[i][j]*float(p[j]) for j in range(3))+m[i][3] for i in range(3))
def rigid64(position,degrees):
 a=math.radians(degrees);c=math.cos(a);s=math.sin(a);x,y,z=map(float,position)
 return ((c,-s,0.,x),(s,c,0.,y),(0.,0.,1.,z),(0.,0.,0.,1.))
